solution_code:
#include <iostream>

class Distance {
private:
    int m_mm{ 0 };

public:
    void setCentimeters(int cm) { m_mm = cm * 10; }
    int getCentimeters() const  { return m_mm / 10; }
    int getMillimeters() const  { return m_mm; }
};

int main() {
    int cm;
    std::cin >> cm;

    Distance d;
    d.setCentimeters(cm);

    std::cout << "cm: " << d.getCentimeters() << '\n';
    std::cout << "mm: " << d.getMillimeters() << '\n';

    return 0;
}
